// Packs the application's own resources into an ARPK container.
//
//   node tools/pack-resources.mjs [out.arpk]
//
// Inputs are authored here or generated by `tools/make-font.mjs`; nothing is taken
// from a third party. The container format is specified in `docs/format-arpk.md`.
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { deflateRawSync } from 'node:zlib';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildContainer, openContainer } from '../src/assets/arpk.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outPath = resolve(process.argv[2] ?? join(root, 'public', 'assets', 'ui.arpk'));
const FONT = join(root, 'assets-src', 'ui-sans.ttf');

// ------------------------------------------------------------------- layers
// Layer ids are small integers; their names live in META so a reader can report
// what a layer is for without knowing this build.
const LAYER = { ui: 0, font: 1 };

// -------------------------------------------------------------------- icons
// 24x24 viewBox, drawn with a single stroke colour so they inherit `currentColor`.
const STROKE = 'fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"';

const ICONS = {
  // An open palm: a rounded body plus four fingers.
  'tool-hand': `
    <path ${STROKE} d="M9 12V5.5a1.5 1.5 0 0 1 3 0V11"/>
    <path ${STROKE} d="M12 11V4.5a1.5 1.5 0 0 1 3 0V11"/>
    <path ${STROKE} d="M15 11.5V6.5a1.5 1.5 0 0 1 3 0V14"/>
    <path ${STROKE} d="M9 12V9.5a1.5 1.5 0 0 0-3 0v4.8c0 3.2 2.4 5.7 5.6 5.7h1.8c2.9 0 5.1-2.3 5.1-5.2"/>`,

  // An I-beam inside a selection band.
  'tool-select': `
    <path ${STROKE} d="M8 5h8M8 19h8M12 5v14"/>
    <rect ${STROKE} x="3" y="3" width="18" height="18" rx="2" stroke-dasharray="3 3"/>`,

  // Magnifier.
  'tool-zoom': `
    <circle ${STROKE} cx="10.5" cy="10.5" r="6"/>
    <path ${STROKE} d="M15 15l5.5 5.5M8 10.5h5M10.5 8v5"/>`,

  // Marquee with corner ticks.
  'tool-snapshot': `
    <path ${STROKE} d="M4 8V5.5A1.5 1.5 0 0 1 5.5 4H8M16 4h2.5A1.5 1.5 0 0 1 20 5.5V8M20 16v2.5a1.5 1.5 0 0 1-1.5 1.5H16M8 20H5.5A1.5 1.5 0 0 1 4 18.5V16"/>
    <rect ${STROKE} x="8" y="8" width="8" height="8" rx="1" stroke-dasharray="2.5 2.5"/>`,

  // Application glyph: a page with a folded corner and a text rule.
  'app': `
    <path ${STROKE} d="M6 3h8l4 4v13a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1z"/>
    <path ${STROKE} d="M14 3v4h4M9 13h6M9 17h4"/>`,

  // Sidebar tabs.
  'tab-thumbnails': `
    <rect ${STROKE} x="3.5" y="4" width="7" height="7" rx="1"/>
    <rect ${STROKE} x="13.5" y="4" width="7" height="7" rx="1"/>
    <rect ${STROKE} x="3.5" y="13" width="7" height="7" rx="1"/>
    <rect ${STROKE} x="13.5" y="13" width="7" height="7" rx="1"/>`,

  'tab-outline': `
    <path ${STROKE} d="M4 6h4M4 12h7M4 18h10"/>
    <circle ${STROKE} cx="19" cy="6" r="1.4"/>`,

  'tab-annotations': `
    <path ${STROKE} d="M4 5.5h16v10H12l-4 3.5v-3.5H4z"/>
    <path ${STROKE} d="M8 9h8M8 12h5"/>`,

  // Selection tool: an arrow cursor over a dashed object outline.
  'tool-pointer': `
    <path ${STROKE} d="M6 3.5l11.5 7.2-4.9 1.2 2.6 5.2-2.2 1.1-2.6-5.2-3.4 3.6z"/>`,

  // Annotation tools.
  'annot-highlight': `
    <path ${STROKE} d="M6 15l6.5-6.5 3 3L9 18H6z"/>
    <path ${STROKE} d="M14.5 5.5l2-2 3 3-2 2z"/>
    <path ${STROKE} d="M4 21h16"/>`,

  'annot-underline': `
    <path ${STROKE} d="M7 4v7a5 5 0 0 0 10 0V4"/>
    <path ${STROKE} d="M5 20h14"/>`,

  'annot-strikeout': `
    <path ${STROKE} d="M7 6.5c1.6-1.6 3.4-2.3 5-2.3 2.4 0 4 1.2 4 3 0 1.5-1.3 2.6-3.6 3.3"/>
    <path ${STROKE} d="M8 17.5c1.2 1.2 2.6 1.8 4.2 1.8 2.5 0 4.1-1.3 4.1-3.1"/>
    <path ${STROKE} d="M4 12h16"/>`,

  'annot-ink': `
    <path ${STROKE} d="M4 19c2.5-1 3.5-4 4.5-7S11 5.5 13 5.5c1.6 0 2.4 1.2 1.6 2.8-1 2-4.4 2.6-4.4 5.2 0 1.4 1.2 2.2 2.6 1.6 2-.8 3.2-3 4.6-2.4 1 .5.6 2.1-.4 3.3"/>`,

  'annot-note': `
    <path ${STROKE} d="M5 4.5h10.5l3.5 3.5v11.5H5z"/>
    <path ${STROKE} d="M15.5 4.5V8H19"/>
    <path ${STROKE} d="M8 12h8M8 15.5h5"/>`,

  'annot-rect': `
    <rect ${STROKE} x="3.5" y="6" width="17" height="12" rx="1.5"/>`,

  'annot-ellipse': `
    <ellipse ${STROKE} cx="12" cy="12" rx="8.5" ry="6"/>`,

  'annot-arrow': `
    <path ${STROKE} d="M4 19L19 5"/>
    <path ${STROKE} d="M13 5h6v6"/>`,

  'annot-textbox': `
    <rect ${STROKE} x="3.5" y="6" width="17" height="12" rx="1.5" stroke-dasharray="3 2.5"/>
    <path ${STROKE} d="M9 10h6M12 10v5"/>`,

  'annot-callout': `
    <path ${STROKE} d="M4 5.5h16v10h-8l-4 4v-4H4z"/>
    <path ${STROKE} d="M8 9h8M8 12h5"/>`,

  // View / annotation-visibility commands.
  'view-hide-annotations': `
    <path ${STROKE} d="M2.5 12S6 6.5 12 6.5c1.5 0 2.8.35 4 .9M21.5 12S18 17.5 12 17.5c-1.5 0-2.8-.35-4-.9"/>
    <path ${STROKE} d="M4 20L20 4"/>`,

  // Settings: a gear, drawn as a ring with teeth.
  settings: `
    <circle ${STROKE} cx="12" cy="12" r="3.4"/>
    <path ${STROKE} d="M12 2.6v3M12 18.4v3M2.6 12h3M18.4 12h3M5.4 5.4l2.1 2.1M16.5 16.5l2.1 2.1M18.6 5.4l-2.1 2.1M7.5 16.5l-2.1 2.1"/>`,

  'page-export': `
    <path ${STROKE} d="M12 3.5v11"/>
    <path ${STROKE} d="M8 10.5l4 4 4-4"/>
    <path ${STROKE} d="M4.5 17v2.5h15V17"/>`,
};

/** Wraps icon markup in a standalone SVG document. */
function svg(body) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="24" height="24" role="img">${body.trim()}</svg>\n`;
}

// --------------------------------------------------------------------- build

const entries = [];
const meta = new Map([
  ['pack.name', 'pdfreader-ui'],
  ['pack.version', '1'],
  ['pack.author', 'self-authored'],
  ['layer.0', 'ui'],
  ['layer.1', 'font'],
]);

if (!existsSync(FONT)) {
  console.error(`缺少字体: ${FONT}\n请先运行: node tools/make-font.mjs assets-src/ui-sans.ttf`);
  process.exit(2);
}
const fontBytes = readFileSync(FONT);
entries.push({
  name: 'font/ui-sans.ttf',
  layer: LAYER.font,
  raw: fontBytes,
  stored: deflateRawSync(fontBytes, { level: 9 }),
  deflate: true,
});

for (const [name, body] of Object.entries(ICONS)) {
  const raw = Buffer.from(svg(body), 'utf8');
  entries.push({
    name: `ui/${name}.svg`,
    layer: LAYER.ui,
    raw,
    stored: deflateRawSync(raw, { level: 9 }),
    deflate: true,
  });
}

const container = buildContainer({ meta, entries });
mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, container);

// ------------------------------------------------------------- self-check

const reopened = openContainer(container);
let failures = 0;
const expect = async (label, ok, detail = '') => {
  if (!ok) failures++;
  console.log(`  ${ok ? '✓' : '✗'} ${label}${detail ? `  ${detail}` : ''}`);
};

console.log(`已生成: ${outPath}`);
console.log(`  容器大小 : ${container.length} 字节`);
console.log(`  资产数量 : ${entries.length}`);
console.log(`  META     : ${meta.size} 项`);
console.log('\n=== 回读自检 ===');
await expect('资产数量一致', reopened.assets.length === entries.length, `${reopened.assets.length}`);
await expect('图层名可解析', reopened.layerName(0) === 'ui' && reopened.layerName(1) === 'font', `${reopened.layerName(0)} / ${reopened.layerName(1)}`);
await expect('ui 层资产数正确', reopened.inLayer(LAYER.ui).length === Object.keys(ICONS).length, `${reopened.inLayer(LAYER.ui).length}`);
await expect('font 层资产数正确', reopened.inLayer(LAYER.font).length === 1, `${reopened.inLayer(LAYER.font).length}`);

const fontBack = await reopened.read('font/ui-sans.ttf');
await expect('字体字节往返一致', fontBack.length === fontBytes.length && Buffer.compare(Buffer.from(fontBack), fontBytes) === 0, `${fontBack.length} 字节`);

for (const name of Object.keys(ICONS)) {
  const back = await reopened.readText(`ui/${name}.svg`);
  const original = svg(ICONS[name]);
  await expect(`${name}.svg 往返一致`, back === original, `${back.length} 字符`);
}

console.log(`\n压缩比: ${(100 - (container.length / (fontBytes.length + Buffer.byteLength(Object.values(ICONS).map(svg).join('')))) * 100).toFixed(1)}% 节省`);
if (failures > 0) {
  console.error(`\n${failures} 项自检失败`);
  process.exitCode = 1;
}
